/* Pure production calculations. No browser, network, or storage dependencies. */
(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.QuestEngine=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
// Shift colour bands in hours relative to the shift budget. On an 8 h budget they reproduce the workbook: red < 6.5, yellow 6.5-7.5, green 7.5-8.05, purple >= 8.05.
const DEFAULT_RATING=Object.freeze({purpleAbove:0.05,greenWithin:0.5,yellowWithin:1.5});
function validateTimings(steps){if(!Array.isArray(steps)||!steps.length||steps.length>999||steps.some(n=>!Number.isFinite(n)||n<0)||!steps.some(n=>n>0))throw new Error('Step durations must be 0 minutes or more, with at least one timed step.');}
function validateRating(rating){const {purpleAbove,greenWithin,yellowWithin}=rating||{};if(![purpleAbove,greenWithin,yellowWithin].every(Number.isFinite)||purpleAbove<0||purpleAbove>4||greenWithin<0||yellowWithin<greenWithin||yellowWithin>8)throw new Error('Colour bands need purple 0-4 h above the budget, and yellow at least as wide as green (up to 8 h).');}
function cumulative(stepMinutes,rateMultiplier=1){let sum=0;return [0,...stepMinutes.map(n=>sum+=n/rateMultiplier)];}
function calculateGoal({start,stepMinutes,productiveMinutes,overtimeMinutes=0,rateMultiplier=1,rule='whole'}){validateTimings(stepMinutes);if(!Number.isInteger(start)||start<0||start>stepMinutes.length)throw new Error('Start must be a completed step within the sequence.');if(!Number.isFinite(productiveMinutes)||productiveMinutes<0||!Number.isFinite(overtimeMinutes)||overtimeMinutes<0||!Number.isFinite(rateMultiplier)||rateMultiplier<=0)throw new Error('Time budgets must be nonnegative and the rate must be positive.');if(!['whole','nearest'].includes(rule))throw new Error('Unknown goal rule.');const cum=cumulative(stepMinutes,rateMultiplier),available=productiveMinutes+overtimeMinutes,target=cum[start]+available;let goal=start;
 // whole: the last step that fits the budget. nearest: the step whose cumulative time is closest to the budget, earliest on ties, as the workbook's INDEX/MATCH(MIN(ABS())) lookup does.
 for(let k=start+1;k<cum.length;k++){if(rule==='whole'){if(cum[k]>target+1e-9)break;goal=k;}else if(Math.abs(cum[k]-target)<Math.abs(cum[goal]-target)-1e-9)goal=k;}
 const used=cum[goal]-cum[start];return {goal,availableMinutes:available,usedMinutes:used,remainingMinutes:Math.max(0,available-used),total:stepMinutes.length,rule};}
function summarize(record){const {start,end,goal,total}=record;if(![start,end,goal,total].every(Number.isInteger)||total<1||start<0||end<start||goal<start||end>total||goal>total)throw new Error('Invalid start, end, goal, or total step.');return {gap:end-goal,completion:Math.round(end/total*100),targetCompletion:Math.round(goal/total*100),goalMet:end>=goal,unitComplete:end===total,attainment:goal>start?Math.round((end-start)/(goal-start)*100):null};}
// Standard minutes between start and stop; completion is by standard time and reaches 100% only at the final step.
function progress({start,end,stepMinutes,rateMultiplier=1}){validateTimings(stepMinutes);const total=stepMinutes.length;if(![start,end].every(Number.isInteger)||start<0||end<start||end>total||!Number.isFinite(rateMultiplier)||rateMultiplier<=0)throw new Error('Invalid start or stop step.');const cum=cumulative(stepMinutes,rateMultiplier);return {earnedMinutes:cum[end]-cum[start],completedMinutes:cum[end],totalMinutes:cum[total],completion:end===total?100:Math.min(99,Math.round(cum[end]/cum[total]*100))};}
// Where a unit sits on its route, as shares of its total standard time, for the line timeline. dayStart is the step the unit started the day on.
// The stop share stops short of 1 until the final step, as completion does.
function timeline({start,end,goal=null,dayStart=start,stepMinutes,rateMultiplier=1}){const p=progress({start,end,stepMinutes,rateMultiplier}),cum=cumulative(stepMinutes,rateMultiplier),share=k=>cum[Math.max(0,Math.min(stepMinutes.length,k))]/p.totalMinutes,stop=end===stepMinutes.length?1:Math.min(0.99,share(end));return {dayStart:Math.min(share(dayStart),stop),stop,goal:goal==null?null:share(goal),remainingMinutes:p.totalMinutes-p.completedMinutes,totalMinutes:p.totalMinutes};}
function rateShift({earnedMinutes,budgetMinutes,rating=DEFAULT_RATING}){if(![earnedMinutes,budgetMinutes].every(Number.isFinite)||earnedMinutes<0||budgetMinutes<=0)return null;const diff=(earnedMinutes-budgetMinutes)/60,e=1e-9;return diff>=rating.purpleAbove-e?'purple':diff>=-rating.greenWithin-e?'green':diff>=-rating.yellowWithin-e?'yellow':'red';}
return {calculateGoal,summarize,validateTimings,validateRating,cumulative,progress,timeline,rateShift,DEFAULT_RATING};
});
